use std::{fs, path::Path};

use anyhow::{anyhow, Context, Result};

use crate::installation_tasks::model::LocalMappingPatchProposal;

const REVIEW_PLACEHOLDER: &str = "REVIEW_AND_SET_CONTAINER_NAME";

pub fn generate_local_mapping_patch_file_content(
    proposals: &[LocalMappingPatchProposal],
    node_id: &str,
    project_id: &str,
) -> String {
    let mut lines = vec![
        "# DATUM local mapping proposal".to_string(),
        format!("# Project: {}", project_id),
        format!("# Node: {}", node_id),
        "# Generated by DATUM for operator review.".to_string(),
        "# This file is advisory only.".to_string(),
        "# It was not applied automatically.".to_string(),
        "# Copy reviewed entries manually into config.toml only after validation.".to_string(),
        "# Do not treat this file as execution permission.".to_string(),
    ];

    if proposals.is_empty() {
        lines.push(String::new());
        lines.push("# No local mapping patch proposals were available.".to_string());
        lines.push("# No config was changed.".to_string());
        return lines.join("\n") + "\n";
    }

    for proposal in proposals {
        lines.push(String::new());
        lines.extend(format_proposal_comment_block(proposal));
        lines.push(String::new());

        if let Some(snippet) = proposal.proposed_config_snippet.as_deref() {
            for line in snippet.lines() {
                lines.push(line.to_string());
            }
        } else if let Some(placeholder) = build_placeholder_snippet(proposal) {
            for line in placeholder.lines() {
                lines.push(line.to_string());
            }
        } else {
            lines.push("# No proposed config snippet was available for this proposal.".to_string());
        }
    }

    lines.join("\n") + "\n"
}

pub fn write_local_mapping_patch_proposal_file(
    output_path: &Path,
    content: &str,
    overwrite: bool,
) -> Result<()> {
    validate_patch_output_path(output_path)?;

    if output_path.exists() && !overwrite {
        return Err(anyhow!(
            "refusing to overwrite existing local mapping patch proposal file {}; pass --overwrite-local-mapping-patch to replace it",
            output_path.display()
        ));
    }

    if let Some(parent) = output_path.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent).with_context(|| {
                format!(
                    "create parent directory for local mapping patch proposal file {}",
                    parent.display()
                )
            })?;
        }
    }

    fs::write(output_path, content).with_context(|| {
        format!(
            "write local mapping patch proposal file {}",
            output_path.display()
        )
    })?;

    Ok(())
}

fn format_proposal_comment_block(proposal: &LocalMappingPatchProposal) -> Vec<String> {
    let mut lines = vec![format!(
        "# Proposal: {}",
        proposal.proposal_id.as_deref().unwrap_or("unknown")
    )];

    if let Some(task_id) = proposal.task_id.as_deref() {
        lines.push(format!("# Task: {}", task_id));
    }
    if let Some(status) = proposal.proposal_status.as_deref() {
        lines.push(format!("# Status: {}", status));
    }
    if let Some(kind) = proposal.proposal_kind.as_deref() {
        lines.push(format!("# Kind: {}", kind));
    }
    if let Some(module_id) = proposal.module_id.as_deref() {
        lines.push(format!("# Module: {}", module_id));
    }
    if let Some(artifact) = proposal.artifact.as_deref() {
        lines.push(format!("# Artifact: {}", artifact));
    }
    if let Some(mapping_key) = proposal.suggested_mapping_key.as_deref() {
        lines.push(format!("# Suggested mapping key: {}", mapping_key));
    }
    if let Some(container_name) = proposal.suggested_container_name.as_deref() {
        lines.push(format!("# Suggested container name: {}", container_name));
    }
    if let Some(reason) = proposal.reason.as_deref() {
        lines.push(format!("# Reason: {}", reason));
    }

    lines.push(format!(
        "# Safe to auto apply: {}",
        proposal.safe_to_auto_apply.unwrap_or(false)
    ));
    lines.push(format!(
        "# Requires operator: {}",
        proposal.requires_operator.unwrap_or(true)
    ));
    lines.push(format!(
        "# Side effects performed: {}",
        proposal.side_effects_performed.unwrap_or(false)
    ));
    lines.push("# This snippet is advisory only and must not be auto-applied.".to_string());
    lines
}

fn build_placeholder_snippet(proposal: &LocalMappingPatchProposal) -> Option<String> {
    let key = proposal.suggested_mapping_key.as_deref()?;
    let section = proposal
        .proposed_config_section
        .as_deref()
        .unwrap_or("dispatch.container_mappings");

    Some(format!(
        "# Placeholder snippet generated because the server did not include proposed_config_snippet.\n# Review and set a real trusted container name before any manual config update.\n[{}]\n\"{}\" = \"{}\"",
        section, key, REVIEW_PLACEHOLDER
    ))
}

fn validate_patch_output_path(output_path: &Path) -> Result<()> {
    let file_name = output_path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    let normalized = normalize_path_text(output_path);

    if file_name == "config.toml" || normalized.ends_with("config.toml") {
        return Err(anyhow!(
            "refusing to write local mapping patch proposal output to config.toml"
        ));
    }

    if file_name == ".env" || normalized.ends_with(".env") {
        return Err(anyhow!(
            "refusing to write local mapping patch proposal output to .env"
        ));
    }

    for forbidden in ["service-account", "serviceaccount", "credential"] {
        if normalized.contains(forbidden) {
            return Err(anyhow!(
                "refusing to write local mapping patch proposal output to suspicious path containing '{}'",
                forbidden
            ));
        }
    }

    Ok(())
}

fn normalize_path_text(path: &Path) -> String {
    path.components()
        .map(|component| component.as_os_str().to_string_lossy().to_string())
        .collect::<Vec<_>>()
        .join("/")
        .to_ascii_lowercase()
}

#[cfg(test)]
mod tests {
    use super::{
        generate_local_mapping_patch_file_content, write_local_mapping_patch_proposal_file,
    };
    use crate::installation_tasks::model::LocalMappingPatchProposal;
    use std::{
        fs,
        path::{Path, PathBuf},
    };

    fn sample_proposal() -> LocalMappingPatchProposal {
        LocalMappingPatchProposal {
            proposal_id: Some("proposal-1".to_string()),
            task_id: Some("task-1".to_string()),
            proposal_status: Some("proposed".to_string()),
            proposal_kind: Some("add_container_mapping".to_string()),
            module_id: Some("chirpstack-primary".to_string()),
            artifact: Some("chirpstack/chirpstack:latest".to_string()),
            suggested_mapping_key: Some("chirpstack-primary".to_string()),
            proposed_config_section: Some("dispatch.container_mappings".to_string()),
            proposed_config_snippet: Some(
                "[dispatch.container_mappings]\n\"chirpstack-primary\" = \"REVIEW_AND_SET_CONTAINER_NAME\""
                    .to_string(),
            ),
            reason: Some(
                "trusted local mapping is required before assisted execution can proceed"
                    .to_string(),
            ),
            safe_to_auto_apply: Some(false),
            requires_operator: Some(true),
            side_effects_performed: Some(false),
            ..LocalMappingPatchProposal::default()
        }
    }

    fn temp_test_dir(label: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!(
            "datum-local-mapping-patch-{}-{}",
            label,
            uuid::Uuid::new_v4()
        ));
        fs::create_dir_all(&dir).expect("temp dir should be created");
        dir
    }

    #[test]
    fn generated_file_content_includes_advisory_header() {
        let rendered = generate_local_mapping_patch_file_content(
            &[sample_proposal()],
            "fog-01",
            "smart-city-campinas",
        );

        assert!(rendered.contains("# DATUM local mapping proposal"));
        assert!(rendered.contains("# This file is advisory only."));
        assert!(rendered
            .contains("# Copy reviewed entries manually into config.toml only after validation."));
    }

    #[test]
    fn generated_file_content_includes_project_and_node() {
        let rendered = generate_local_mapping_patch_file_content(
            &[sample_proposal()],
            "fog-01",
            "smart-city-campinas",
        );

        assert!(rendered.contains("# Project: smart-city-campinas"));
        assert!(rendered.contains("# Node: fog-01"));
    }

    #[test]
    fn generated_file_content_includes_proposal_metadata_and_safety_fields() {
        let rendered = generate_local_mapping_patch_file_content(
            &[sample_proposal()],
            "fog-01",
            "smart-city-campinas",
        );

        assert!(rendered.contains("# Proposal: proposal-1"));
        assert!(rendered.contains("# Task: task-1"));
        assert!(rendered.contains("# Status: proposed"));
        assert!(rendered.contains("# Kind: add_container_mapping"));
        assert!(rendered.contains(
            "# Reason: trusted local mapping is required before assisted execution can proceed"
        ));
        assert!(rendered.contains("# Safe to auto apply: false"));
        assert!(rendered.contains("# Requires operator: true"));
    }

    #[test]
    fn generated_file_content_includes_proposed_config_snippet_when_present() {
        let rendered = generate_local_mapping_patch_file_content(
            &[sample_proposal()],
            "fog-01",
            "smart-city-campinas",
        );

        assert!(rendered.contains("[dispatch.container_mappings]"));
        assert!(rendered.contains("\"chirpstack-primary\" = \"REVIEW_AND_SET_CONTAINER_NAME\""));
    }

    #[test]
    fn generated_file_content_uses_placeholder_when_needed() {
        let mut proposal = sample_proposal();
        proposal.proposed_config_snippet = None;

        let rendered =
            generate_local_mapping_patch_file_content(&[proposal], "fog-01", "smart-city-campinas");

        assert!(rendered.contains(
            "# Placeholder snippet generated because the server did not include proposed_config_snippet."
        ));
        assert!(rendered.contains("\"chirpstack-primary\" = \"REVIEW_AND_SET_CONTAINER_NAME\""));
    }

    #[test]
    fn empty_proposals_generate_safe_explanatory_content() {
        let rendered =
            generate_local_mapping_patch_file_content(&[], "fog-01", "smart-city-campinas");

        assert!(rendered.contains("# No local mapping patch proposals were available."));
        assert!(rendered.contains("# No config was changed."));
    }

    #[test]
    fn write_helper_refuses_config_toml() {
        let result = write_local_mapping_patch_proposal_file(
            Path::new("generated/config.toml"),
            "content",
            false,
        );

        assert!(result.is_err());
    }

    #[test]
    fn write_helper_refuses_env() {
        let result =
            write_local_mapping_patch_proposal_file(Path::new("generated/.env"), "content", false);

        assert!(result.is_err());
    }

    #[test]
    fn write_helper_refuses_credential_like_paths() {
        let result = write_local_mapping_patch_proposal_file(
            Path::new("generated/service-account-credential.toml"),
            "content",
            false,
        );

        assert!(result.is_err());
    }

    #[test]
    fn write_helper_refuses_overwrite_without_flag() {
        let dir = temp_test_dir("overwrite-refusal");
        let path = dir.join("proposal.toml");
        fs::write(&path, "existing").expect("seed file should be written");

        let result = write_local_mapping_patch_proposal_file(&path, "new content", false);

        assert!(result.is_err());
        assert_eq!(
            fs::read_to_string(&path).expect("existing file should remain readable"),
            "existing"
        );

        let _ = fs::remove_dir_all(dir);
    }

    #[test]
    fn write_helper_writes_temp_path() {
        let dir = temp_test_dir("write-ok");
        let path = dir.join("generated").join("local-mapping-proposal.toml");

        write_local_mapping_patch_proposal_file(&path, "first", false)
            .expect("first write should succeed");
        write_local_mapping_patch_proposal_file(&path, "second", true)
            .expect("overwrite write should succeed");

        assert_eq!(
            fs::read_to_string(&path).expect("written file should be readable"),
            "second"
        );

        let _ = fs::remove_dir_all(dir);
    }

    #[test]
    fn patch_file_source_guard_has_no_docker_or_shell_execution() {
        let source = include_str!("patch_file.rs");
        let implementation = source
            .split("#[cfg(test)]")
            .next()
            .expect("implementation section should exist");

        for forbidden in [
            "docker run",
            "docker pull",
            "docker rm",
            "docker inspect",
            "Command::new",
            "std::process::Command",
        ] {
            assert!(
                !implementation.contains(forbidden),
                "patch file helper must not contain forbidden pattern: {forbidden}"
            );
        }
    }
}
